function u2RouteNetwork(){return `<div class="u2-route-net"><div class="route-node europe"><span>🌍</span><b>歐洲市場</b><small>想取得香料、絲織品、瓷器等亞洲商品</small></div><i>⇄</i><div class="route-column"><div class="route-node"><span>🇮🇩</span><b>東南亞／印尼</b><small>荷蘭的重要亞洲據點</small></div><div class="route-node"><span>🇵🇭</span><b>菲律賓</b><small>西班牙的重要東亞基地</small></div></div><i>⇄</i><div class="route-node taiwan"><span>🏝️</span><b>臺灣</b><small>連接中國沿海、日本與東南亞的海路節點</small></div><i>⇄</i><div class="route-column"><div class="route-node"><span>🇯🇵</span><b>日本</b><small>銀、鹿皮等交易</small></div><div class="route-node"><span>🧵</span><b>中國沿海</b><small>絲織品、瓷器與人口移動</small></div></div></div><p class="diagram-note">這是「關係圖」，不是比例地圖。目的在看誰和誰透過海路連在一起。</p>`}
