function u22Society(){return `<div class="society-balance"><section><span>🏫</span><b>教育與制度</b><p>鄭氏在臺南興建孔廟、設學校，培育人才，擴大漢人儒學文化。</p></section><section><span>🧳</span><b>移民與信仰</b><p>漢人移民增加，也把媽祖、玄天上帝等信仰與生活習俗帶入臺灣。</p></section><section><span>🌾</span><b>土地開墾</b><p>屯墾與移民使農業與聚落擴大，也改變土地使用。</p></section><section><span>⚠️</span><b>原住民族受到的衝擊</b><p>外來統治、傳教與開墾可能造成土地壓力、文化改變與衝突；原住民族也會做出協商、抵抗或調整。</p></section></div><div class="exam-focus"><b>🎯 第二課真正核心</b><span>「文化資產＋貿易網＋人口移動＋不同族群的影響」四條線要一起看，不能只背城堡。</span></div>`}
function setupMiniMission(selector, questions, onDone){
  const box=$(selector);
  if(!box) return;
  let idx=0;
  function draw(){
    const q=questions[idx];
    box.innerHTML=`
      <div class="mini-mission-q">
        <span>${idx+1}/${questions.length}</span>
        <h4>${q[0]}</h4>
        <div class="choice-3">
          ${shuffled(q[1].map((o,i)=>({o,i}))).map(z=>`<button data-mi="${z.i}">${z.o}</button>`).join('')}
        </div>
        <p class="feedback"></p>
      </div>`;
    box.querySelectorAll('[data-mi]').forEach(btn=>{
      btn.onclick=()=>{
        const ok=Number(btn.dataset.mi)===q[2];
        const fb=box.querySelector('.feedback');
        if(ok){
          fb.textContent='答對，解鎖下一張線索。';
          btn.classList.add('correct');
          box.querySelectorAll('button').forEach(x=>x.disabled=true);
          setTimeout(()=>{
            idx++;
            if(idx>=questions.length){
              box.innerHTML='<div class="mission-done">✅ 線索全部解鎖！</div>';
              if(onDone) onDone();
            }else{
              draw();
            }
          },350);
        }else{
          btn.classList.add('wrong');
          btn.disabled=true;
          fb.textContent='再想一下：'+q[3];
        }
      };
    });
  }
  draw();
}

