function v10Record(config){state[config.recordKey]=state[config.recordKey]||{plays:0,bestCoins:0,bestCorrect:0,bestCollection:0};return state[config.recordKey]}
function v10RecentKey(config,space){return `v10:${config.id}:${space.key}`}
function v10PickFresh(config,space,pool){state.gameQuestionMemory=state.gameQuestionMemory||{};const key=v10RecentKey(config,space),recent=state.gameQuestionMemory[key]||[],sessionUsed=v10GameSession.used[key]||[];let candidates=pool.filter(x=>!recent.includes(x[0])&&!sessionUsed.includes(x[0]));if(!candidates.length)candidates=pool.filter(x=>!sessionUsed.includes(x[0]));if(!candidates.length){v10GameSession.used[key]=[];candidates=pool.filter(x=>!recent.slice(-1).includes(x[0]));}if(!candidates.length)candidates=pool;const q=candidates[Math.floor(Math.random()*candidates.length)];v10GameSession.used[key]=[...(v10GameSession.used[key]||[]),q[0]];state.gameQuestionMemory[key]=[...recent.filter(x=>x!==q[0]),q[0]].slice(-3);saveState();return q}
