function v10CatName(c){return v10GameSession.config.catNames[c]||'旅程事件'}
function v10Stats(){const g=v10GameSession,c=g.config;if(!g)return;$('#gTurn').textContent=`${g.turn}/${c.maxTurns}`;$('#gCoins').textContent=g.coins;$('#gA').textContent=g.collections.assets.size;$('#gC').textContent=[...g.collections.cargo.values()].reduce((a,b)=>a+b,0);$('#gE').textContent=g.collections.evidence.size;$('#gB').textContent=g.collections.badges.size;$('#gAcc').textContent=g.totalQ?Math.round(g.correct/g.totalQ*100)+'%':'—'}
function v10CollectionHtml(){const g=v10GameSession,c=g.config,cargo=[...g.collections.cargo.entries()].map(([k,v])=>`${k}×${v}`);return `<div><b>${c.labels.assets}</b><span>${[...g.collections.assets].join('、')||'還沒有'}</span></div><div><b>${c.labels.cargo}</b><span>${cargo.join('、')||'還沒有'}</span></div><div><b>${c.labels.evidence}</b><span>${[...g.collections.evidence].join('、')||'還沒有'}</span></div><div><b>${c.labels.badges}</b><span>${[...g.collections.badges].join('、')||'還沒有'}</span></div>`}
function v10RenderCollection(){const el=$('#gameCollection');if(el)el.innerHTML=v10CollectionHtml()}
function v10RenderLog(){const el=$('#gameLog');if(el)el.innerHTML=v10GameSession.log.slice(-12).reverse().map(x=>`<p>${escapeHtml(x)}</p>`).join('')}
function v10CenterDefault(){const c=v10GameSession.config;return `<div class="game-center-home v10-center-home"><div class="dice-face" id="diceFace">🎲</div><h3>擲骰子，破解一格線索</h3><p>棋格不公布答案；答對後才揭曉。踩回舊格會優先換一題。</p><button class="primary-btn game-big-btn" id="rollDice">擲骰子</button><small>每局 ${c.maxTurns} 回合。最近做過的題目也會盡量避開。</small></div>`}
function v10RenderBoard(){const g=v10GameSession,c=g.config,rec=v10Record(c);$('#gameContent').innerHTML=`<div class="game-head"><div><span class="pill game-pill">🎲 第${c.unit}單元遊戲</span><h2>${c.title}</h2><p>${c.subtitle}</p><div class="game-record"><span>已玩 <b>${rec.plays||0}</b> 局</span><span>最佳 <b>${rec.bestCorrect||0}%</b></span></div></div><button class="secondary-btn" id="restartGameTop">↻ 重新開局</button></div><div class="game-statbar v10-statbar"><span>回合 <b id="gTurn">0/${c.maxTurns}</b></span><span>💰 <b id="gCoins">${c.startCoins}</b></span><span>${c.labels.assets} <b id="gA">0</b></span><span>${c.labels.cargo} <b id="gC">0</b></span><span>${c.labels.evidence} <b id="gE">0</b></span><span>${c.labels.badges} <b id="gB">0</b></span><span>🎯 <b id="gAcc">—</b></span></div><div class="board-scroll"><div class="treasure-board v10-board" id="treasureBoard">${c.board.map(v10BoardSpace).join('')}<div class="game-center v10-game-center" id="gameCenter">${v10CenterDefault()}</div><div class="player-token" id="playerToken">🧭</div></div></div><div class="game-bottom"><details><summary>📦 我的收藏</summary><div id="gameCollection" class="game-collection"></div></details><details><summary>🧾 這局發生什麼？</summary><div id="gameLog" class="game-log"></div></details></div>`;v10Position();$('#rollDice').onclick=v10Roll;$('#restartGameTop').onclick=()=>openTreasureGame(c.id,true);v10Stats();v10RenderCollection();v10RenderLog()}
function v10Position(){const el=$('#playerToken'),space=$(`[data-v10-space="${v10GameSession.pos}"]`),board=$('#treasureBoard');if(!el||!space||!board)return;const b=board.getBoundingClientRect(),r=space.getBoundingClientRect();el.style.left=(r.left-b.left+r.width/2)+'px';el.style.top=(r.top-b.top+r.height/2)+'px';$$('[data-v10-space]').forEach(x=>x.classList.toggle('active-space',Number(x.dataset.v10Space)===v10GameSession.pos))}
async function v10Roll(){const g=v10GameSession,c=g.config;if(g.busy||g.turn>=c.maxTurns)return;g.busy=true;const roll=1+Math.floor(Math.random()*6),face=$('#diceFace'),btn=$('#rollDice');if(btn)btn.disabled=true;for(let k=0;k<5;k++){if(face)face.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][Math.floor(Math.random()*6)];await new Promise(r=>setTimeout(r,65))}if(face)face.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][roll-1];g.turn++;g.log.push(`🎲 第${g.turn}回合：${roll}點。`);for(let i=0;i<roll;i++){const old=g.pos;g.pos=(g.pos+1)%c.board.length;if(g.pos===0&&old!==0){g.coins+=50;g.log.push('🚩 繞回總部，補給 +50。')}v10Position();await new Promise(r=>setTimeout(r,125))}v10Stats();v10RenderLog();v10Resolve()}
function v10Resolve(){const g=v10GameSession,s=g.config.board[g.pos];if(s.type==='start'){v10Message('🚩','回到探險總部','補給完成，準備下一回合。');return}if(s.type==='event'){const e=v10PickFresh(g.config,{key:'events'},g.config.events.map(x=>x.q));const event=g.config.events.find(x=>x.q[0]===e[0]);v10ShowQuestion(event,true);return}v10ShowQuestion(s,false)}
function v10Message(icon,title,text){$('#gameCenter').innerHTML=`<div class="game-event-icon">${icon}</div><span class="mini-kicker">旅程事件</span><h3>${title}</h3><p>${text}</p><button class="primary-btn game-big-btn" id="gameContinue">下一回合</button>`;$('#gameContinue').onclick=v10FinishTurn}
function v10Reward(item,half=false){const g=v10GameSession,r=item.reward||{},coins=half?Math.round((r.coins||70)/2):(r.coins||70);g.coins+=coins;if(r.group==='cargo')g.collections.cargo.set(r.name,(g.collections.cargo.get(r.name)||0)+1);else if(r.group&&g.collections[r.group])g.collections[r.group].add(r.name);g.log.push(`✅ 解鎖「${item.reveal||item.label}」＋${coins}`);v10Stats();v10RenderCollection();v10RenderLog()}
function v10ShowQuestion(item,isEvent){const g=v10GameSession,c=g.config,q=isEvent?item.q:v10PickFresh(c,item,item.q);g.totalQ++;let wrong=0;const opts=q[1].map((o,i)=>({o,i}));$('#gameCenter').innerHTML=`<div class="game-space-title v10-title"><span>${item.icon}</span><div><small>${isEvent?'機會／命運挑戰':v10CatName(item.cat)}</small><h3>${item.label}</h3></div></div><div class="mystery-lock">🔒 答對才揭曉這一格真正代表什麼</div><div class="game-question-row"><p class="game-question v10-game-question">${q[0]}</p><button class="speech-btn mini-speech" type="button" data-speech="${encodeURIComponent(q[0]+'。'+q[1].join('、'))}" aria-label="朗讀題目">🔊</button></div><div class="game-choices v10-choices">${shuffled(opts).map(z=>`<button data-game-answer="${z.i}">${escapeHtml(z.o)}</button>`).join('')}</div><p id="gameFeedback" class="feedback"></p>`;$('#gameCenter').querySelectorAll('[data-game-answer]').forEach(b=>b.onclick=()=>{const ok=Number(b.dataset.gameAnswer)===q[2],fb=$('#gameFeedback');if(ok){if(wrong===0)g.correct++;b.classList.add('correct');$('#gameCenter').querySelectorAll('[data-game-answer]').forEach(x=>x.disabled=true);v10Reward(item,wrong>0);setTimeout(()=>{const reveal=item.reveal||item.label;const card=document.createElement('div');card.className='game-memory-tip reveal-card';card.innerHTML=`<b>🔓 解鎖：${escapeHtml(reveal)}</b><span>${escapeHtml(q[4]||q[3])}</span><button class="primary-btn game-big-btn" id="gameContinue">下一回合</button>`;$('#gameCenter').appendChild(card);$('#gameContinue').onclick=v10FinishTurn},300)}else{wrong++;b.classList.add('wrong');b.disabled=true;fb.textContent=`還沒破解。提示：${q[3]}`;g.log.push(`🧠 ${item.label} 第${wrong}次未解開。`);v10RenderLog()}});v10Stats()}
function v10FinishTurn(){const g=v10GameSession;g.busy=false;if(g.turn>=g.config.maxTurns){v10FinishGame();return}$('#gameCenter').innerHTML=v10CenterDefault();$('#rollDice').onclick=v10Roll;v10Stats()}
function v10FinishGame(){const g=v10GameSession,c=g.config,acc=g.totalQ?Math.round(g.correct/g.totalQ*100):0,count=v10CollectionCount(g),rec=v10Record(c);rec.plays++;rec.bestCoins=Math.max(rec.bestCoins||0,g.coins);rec.bestCorrect=Math.max(rec.bestCorrect||0,acc);rec.bestCollection=Math.max(rec.bestCollection||0,count);state.stars+=Math.max(3,Math.round(acc/20));saveState();renderState();$('#gameCenter').innerHTML=`<div class="game-finish"><span>🏆</span><h3>這局任務完成！</h3><div class="finish-metrics"><b>💰 ${g.coins}</b><b>${c.labels.assets} ${g.collections.assets.size}</b><b>${c.labels.cargo} ${[...g.collections.cargo.values()].reduce((a,b)=>a+b,0)}</b><b>${c.labels.evidence} ${g.collections.evidence.size}</b><b>${c.labels.badges} ${g.collections.badges.size}</b><b>🎯 ${acc}%</b></div><div class="finish-collection">${v10CollectionHtml()}</div><p>${acc>=80?'已經能穩定破解線索。再玩一局時，重複棋格會優先出不同題。':'再玩一局，把同一概念換題型重複提取，比重讀課文更有效。'}</p><button class="primary-btn game-big-btn" id="playAgain">🎲 再玩一次</button><button class="secondary-btn" id="backUnit">📚 回本單元</button></div>`;$('#playAgain').onclick=()=>openTreasureGame(c.id,true);$('#backUnit').onclick=()=>{$('#gameDialog').close();openUnit(c.unit)};v10Stats()}
function openTreasureGame(id,reset=true){const c=V10_GAME_CONFIGS[id];if(reset||!v10GameSession||v10GameSession.config.id!==id)v10GameSession=v10NewGame(c);v10RenderBoard();if(!$('#gameDialog').open)$('#gameDialog').showModal()}
openUnit1Game=function(){openTreasureGame('u1',true)};
function openUnit2Game(){openTreasureGame('u2',true)}
window.addEventListener('resize',()=>{if(v10GameSession&&$('#gameDialog')?.open)v10Position()});

/* ---------- Home + unit entries: only current unit game shown ---------- */
const v10RenderStateBase=renderState;
renderState=function(){v10RenderStateBase();const current=firstIncompleteUnit();const u1=$('#unit1GameCard'),u2=$('#unit2GameCard');if(u1)u1.hidden=current!==1;if(u2){const visible=current===2;u2.hidden=!visible;const rec=v10Record(V10_GAME_CONFIGS.u2),el=$('#gameRecord2');if(el){el.hidden=!rec.plays;el.innerHTML=rec.plays?`<span>已玩 <b>${rec.plays}</b> 局</span><span>最佳 <b>${rec.bestCorrect}%</b></span>`:''}}const r1=v10Record(V10_GAME_CONFIGS.u1),el1=$('#gameRecord');if(el1){el1.hidden=!r1.plays;el1.innerHTML=r1.plays?`<span>已玩 <b>${r1.plays}</b> 局</span><span>最佳 <b>${r1.bestCorrect}%</b></span>`:''}}
const b2=$('#openUnit2Game');if(b2)b2.onclick=openUnit2Game;

const v10OpenUnitBase=openUnit;
openUnit=function(n){v10OpenUnitBase(n);const box=$('#unitContent');if(!box)return;if(n===1){const old=box.querySelector('#unitGameInline');if(old){old.querySelector('b').textContent='把三課混在一起破解';old.querySelector('p').textContent='棋格只顯示線索；重複踩格會換題。';old.querySelector('button').onclick=()=>{$('#unitDialog').close();openUnit1Game()}}}if(n===2&&!box.querySelector('#unit2GameInline')){const div=document.createElement('section');div.id='unit2GameInline';div.className='unit-game-inline';div.innerHTML='<span>⛵</span><div><b>把兩課變成航海任務</b><p>航路、古堡、貨物、年代與文化影響混在同一局。</p></div><button class="primary-btn">玩大航海航路任務局</button>';div.querySelector('button').onclick=()=>{$('#unitDialog').close();openUnit2Game()};box.appendChild(div)}};

